// dialogs.js
// ==================================================
// WEBSHELF DIALOGS
// ==================================================

(() => {
  let overlay = null;
  let resolver = null;
  let previousFocus = null;
  let restoreBackground = null;

  function ensureDialog() {
    if (overlay) return;

    overlay = document.createElement("div");
    overlay.className = "webshelf-dialog-overlay";
    overlay.hidden = true;
    overlay.innerHTML = `
      <div class="webshelf-dialog" role="dialog" aria-modal="true" aria-labelledby="webshelf-dialog-title" aria-describedby="webshelf-dialog-message">
        <div class="webshelf-dialog-icon" aria-hidden="true">!</div>
        <div class="webshelf-dialog-copy">
          <h2 id="webshelf-dialog-title"></h2>
          <p id="webshelf-dialog-message"></p>
        </div>
        <div class="webshelf-dialog-actions">
          <button class="webshelf-dialog-cancel" type="button">Cancel</button>
          <button class="webshelf-dialog-confirm" type="button">Confirm</button>
        </div>
      </div>`;

    document.body.appendChild(overlay);

    overlay.querySelector(".webshelf-dialog-cancel").addEventListener("click", () => finish(false));
    overlay.querySelector(".webshelf-dialog-confirm").addEventListener("click", () => finish(true));
    overlay.addEventListener("click", (event) => {
      if (event.target === overlay) finish(false);
    });

    document.addEventListener("keydown", (event) => {
      if (overlay.hidden) return;
      if (event.key === "Tab") {
        const buttons = [...overlay.querySelectorAll("button")];
        const target = event.shiftKey ? buttons.at(-1) : buttons[0];
        if ((event.shiftKey && document.activeElement === buttons[0]) || (!event.shiftKey && document.activeElement === buttons.at(-1))) { event.preventDefault(); target.focus(); }
      }
      if (event.key === "Escape") {
        event.preventDefault();
        finish(false);
      }
    });
  }

  function finish(value) {
    if (!overlay || overlay.hidden) return;
    overlay.hidden = true;
    restoreBackground?.(); restoreBackground = null;
    document.body.classList.remove("dialog-open");
    const done = resolver;
    resolver = null;
    const focus = previousFocus;
    previousFocus = null;
    if (focus && typeof focus.focus === "function" && document.contains(focus)) focus.focus();
    done?.(value);
  }

  function confirm(options = {}) {
    ensureDialog();
    if (resolver) finish(false);

    const settings = typeof options === "string" ? { message: options } : options;
    window.WebShelfSearch?.close?.();
    previousFocus = document.activeElement;

    const title = overlay.querySelector("#webshelf-dialog-title");
    const message = overlay.querySelector("#webshelf-dialog-message");
    const confirmButton = overlay.querySelector(".webshelf-dialog-confirm");
    const cancelButton = overlay.querySelector(".webshelf-dialog-cancel");
    const icon = overlay.querySelector(".webshelf-dialog-icon");

    title.textContent = settings.title || "Are you sure?";
    message.textContent = settings.message || "This action cannot be undone.";
    confirmButton.textContent = settings.confirmText || "Confirm";
    cancelButton.textContent = settings.cancelText || "Cancel";
    confirmButton.classList.toggle("danger", Boolean(settings.danger));
    icon.classList.toggle("danger", Boolean(settings.danger));

    overlay.hidden = false;
    restoreBackground = WebShelfRuntime.modalBackground(overlay);
    document.body.classList.add("dialog-open");
    requestAnimationFrame(() => { if (!overlay.hidden) cancelButton.focus(); });

    return new Promise((resolve) => {
      resolver = resolve;
    });
  }

  window.WebShelfDialog = { confirm, close: () => finish(false) };
})();

;

// favorites.js
// ==================================================
// WEBSHELF FAVORITES
// ==================================================

const FAVORITES_KEY = "webshelf-favorites";
const FAVORITES_VISIBLE_LIMIT = 5;
let favoritesExpanded = false;

function getFavorites() {
  return WebShelfRuntime.savedSites(FAVORITES_KEY);
}

function saveFavorites(favorites) {
  WebShelfRuntime.storage.setItem(FAVORITES_KEY, JSON.stringify(favorites));
}

function isFavorite(siteUrl) {
  return getFavorites().some((site) => site.url === siteUrl);
}

function toggleFavorite(site) {
  const favorites = getFavorites();
  const index = favorites.findIndex((favorite) => favorite.url === site.url);

  if (index !== -1) favorites.splice(index, 1);
  else favorites.push(site);

  saveFavorites(favorites);
  return isFavorite(site.url);
}

function updateFavoriteButton(button, active) {
  if (!button) return;
  button.classList.toggle("active", active);
  button.textContent = active ? "★" : "☆";
  button.setAttribute("aria-pressed", String(active));
  button.setAttribute("aria-label", active ? "Remove from favorites" : "Add to favorites");
}

function createFavoriteButton(site) {
  const button = document.createElement("button");
  button.className = "favorite-button";
  button.type = "button";
  button.dataset.siteUrl = site.url;
  updateFavoriteButton(button, isFavorite(site.url));
  button.addEventListener("click", (event) => {
    event.preventDefault();
    event.stopPropagation();
    const active = toggleFavorite(site);
    updateFavoriteButton(button, active);
    document.dispatchEvent(new CustomEvent("webshelf-favorites-changed"));
  });
  return button;
}

function renderFavorites() {
  const section = document.querySelector("#favorites-section");
  const list = document.querySelector("#favorites-list");
  if (!section || !list) return;

  const favorites = getFavorites();

  if (!favorites.length) {
    section.hidden = true;
    list.innerHTML = "";
    favoritesExpanded = false;
    return;
  }

  section.hidden = false;
  const visible = favoritesExpanded
    ? favorites
    : favorites.slice(0, FAVORITES_VISIBLE_LIMIT);

  const rows = visible.map((site, index) => {
    const rank = String(index + 1).padStart(2, "0");
    const logo = site.icon
      ? `<img src="${escapeWebShelfText(site.icon)}" loading="lazy" decoding="async" alt="${escapeWebShelfText(site.name)} logo">`
      : `<span>${escapeWebShelfText(site.name.charAt(0))}</span>`;

    return `
      <div class="site-row favorite-site-row" data-site-url="${escapeWebShelfText(site.url)}">
        <a class="site-link" href="${escapeWebShelfText(site.url)}" target="_blank" rel="noopener noreferrer">
          <span class="rank">${rank}</span>
          <div class="site-logo">${logo}</div>
          <span class="site-name-line">
            <span class="site-name">${escapeWebShelfText(site.name)}</span>
            ${typeof renderSiteBadges === "function" ? renderSiteBadges(site) : ""}
          </span>
        </a>
        <button class="favorite-button active" type="button" data-site-url="${escapeWebShelfText(site.url)}" aria-label="Remove from favorites">★</button>
      </div>`;
  }).join("");

  const toggle = favorites.length > FAVORITES_VISIBLE_LIMIT
    ? `<button class="favorites-view-all" type="button" data-favorites-view-all>${favoritesExpanded ? "Show less" : `View all (${favorites.length})`}</button>`
    : "";

  list.innerHTML = rows + toggle;

  list.querySelectorAll(".favorite-button").forEach((button) => {
    const site = favorites.find((item) => item.url === button.dataset.siteUrl);
    if (!site) return;

    button.addEventListener("click", (event) => {
      event.preventDefault();
      event.stopPropagation();
      toggleFavorite(site);
      document.dispatchEvent(new CustomEvent("webshelf-favorites-changed"));
    });
  });

  list.querySelector("[data-favorites-view-all]")?.addEventListener("click", () => {
    favoritesExpanded = !favoritesExpanded;
    renderFavorites();
  });

  document.dispatchEvent(new CustomEvent("webshelf-sites-rendered"));
}

function syncFavoriteButtons() {
  document.querySelectorAll(".favorite-button[data-site-url]").forEach((button) => {
    updateFavoriteButton(button, isFavorite(button.dataset.siteUrl));
  });
}

async function clearFavorites() {
  const favorites = getFavorites();
  if (!favorites.length) return;

  const confirmed = window.WebShelfDialog
    ? await window.WebShelfDialog.confirm({
        title: "Clear favorites?",
        message: "This removes every saved favorite from this browser.",
        confirmText: "Clear favorites",
        danger: true
      })
    : true;

  if (!confirmed) return;

  WebShelfRuntime.storage.removeItem(FAVORITES_KEY);
  favoritesExpanded = false;
  document.dispatchEvent(new CustomEvent("webshelf-favorites-changed"));
}

document.addEventListener("webshelf-favorites-changed", () => {
  renderFavorites();
  syncFavoriteButtons();
});

function initializeFavorites() {
  renderFavorites();
  syncFavoriteButtons();
  document.querySelector("#favorites-clear")?.addEventListener("click", clearFavorites);
}

if (document.readyState === "loading") {
  document.addEventListener("DOMContentLoaded", initializeFavorites);
} else {
  initializeFavorites();
}

;

// category.js
// ==================================================
// CATEGORY PAGE
// ==================================================

const urlParams = new URLSearchParams(window.location.search);
const categoryType = urlParams.get("type");
const currentCategory = WebShelfCategories.find((category) => category.key === categoryType);

const pageTitle = document.querySelector("#category-page-title");
const pageCount = document.querySelector("#category-page-count");
const pageList = document.querySelector("#category-page-list");
const pageIcon = document.querySelector("#category-page-icon");
const lucideIcon = document.querySelector("#category-page-lucide");
const categoryCanonical = document.querySelector("#category-canonical");
const categoryDescription = document.querySelector("#category-description");
const siteFilters = document.querySelector("#category-site-filters");

let activeSiteFilter = "all";

function visibleSites(sites) {
  return typeof filterVisibleSites === "function"
    ? filterVisibleSites(sites)
    : sites;
}

function categorySiteRow(site, index) {
  const rank = String(index + 1).padStart(2, "0");
  const logo = site.icon
    ? `<img src="${escapeWebShelfText(site.icon)}" loading="lazy" decoding="async" alt="${escapeWebShelfText(site.name)} logo">`
    : `<span>${escapeWebShelfText(site.name.charAt(0))}</span>`;

  return `
    <div class="site-row" data-site-url="${escapeWebShelfText(site.url)}">
      <a class="site-link" href="${escapeWebShelfText(site.url)}" target="_blank" rel="noopener noreferrer">
        <span class="rank">${rank}</span>
        <div class="site-logo">${logo}</div>
        <span class="site-name-line">
          <span class="site-name">${escapeWebShelfText(site.name)}</span>
          ${renderSiteBadges(site)}
        </span>
      </a>
      <button class="favorite-button" type="button" data-site-url="${escapeWebShelfText(site.url)}" aria-label="Add to favorites">☆</button>
    </div>
  `;
}

function setupCategoryFavorites(sites) {
  pageList.querySelectorAll(".favorite-button").forEach((button) => {
    const site = sites.find((item) => item.url === button.dataset.siteUrl);
    if (!site) return;

    updateFavoriteButton(button, isFavorite(site.url));
    button.addEventListener("click", () => {
      const active = toggleFavorite(site);
      updateFavoriteButton(button, active);
      document.dispatchEvent(new CustomEvent("webshelf-favorites-changed"));
    });
  });
}

function filterKeyForBadge(badge) {
  return `badge:${String(badge).toLowerCase()}`;
}

function siteMatchesFilter(site, filter) {
  if (filter === "all") return true;
  if (filter === "screenshots") return Array.isArray(site.screenshots) && site.screenshots.length > 0;
  if (filter === "mirrors") return Array.isArray(site.links) && site.links.some((link) => link?.url);
  if (filter === "highlights") return Array.isArray(site.highlights) && site.highlights.length > 0;
  if (filter.startsWith("badge:")) {
    const badge = filter.slice(6);
    return getSiteBadges(site).some((value) => value.toLowerCase() === badge);
  }
  return true;
}

function getFilterOptions() {
  if (!currentCategory) return [];
  const sites = visibleSites(currentCategory.sites);
  const badges = [...new Set(sites.flatMap((site) => getSiteBadges(site)))].sort((a, b) => a.localeCompare(b));
  const filters = [{ key: "all", label: "All" }];
  badges.forEach((badge) => filters.push({ key: filterKeyForBadge(badge), label: badge }));
  if (sites.some((site) => Array.isArray(site.screenshots) && site.screenshots.length)) filters.push({ key: "screenshots", label: "Screenshots" });
  if (sites.some((site) => Array.isArray(site.links) && site.links.some((link) => link?.url))) filters.push({ key: "mirrors", label: "Mirrors" });
  if (sites.some((site) => Array.isArray(site.highlights) && site.highlights.length)) filters.push({ key: "highlights", label: "Highlights" });
  return filters;
}

function renderFilters() {
  if (!siteFilters || !currentCategory) return;
  const options = getFilterOptions();
  if (options.length <= 1) {
    siteFilters.hidden = true;
    siteFilters.innerHTML = "";
    return;
  }

  siteFilters.hidden = false;
  siteFilters.innerHTML = options.map((option) => `
    <button
      class="site-filter-chip ${option.key === activeSiteFilter ? "active" : ""}"
      type="button"
      aria-pressed="${option.key === activeSiteFilter}" data-site-filter="${escapeWebShelfText(option.key)}"
    >${escapeWebShelfText(option.label)}</button>
  `).join("");
}

function renderCategorySites() {
  if (!currentCategory || !pageList) return;
  const allVisible = visibleSites(currentCategory.sites);
  const filtered = allVisible.filter((site) => siteMatchesFilter(site, activeSiteFilter));

  pageCount.textContent = activeSiteFilter === "all"
    ? `${allVisible.length} ${allVisible.length === 1 ? "site" : "sites"}`
    : `${filtered.length} of ${allVisible.length} sites`;

  if (!filtered.length) {
    pageList.innerHTML = `
      <div class="category-empty">
        <h2>No matching sites</h2>
        <p>Try another filter.</p>
      </div>
    `;
  } else {
    pageList.innerHTML = filtered.map(categorySiteRow).join("");
    setupCategoryFavorites(filtered);
    document.dispatchEvent(new CustomEvent("webshelf-sites-rendered"));
  }

  renderFilters();
}

function applyBadge(badge) {
  const key = filterKeyForBadge(badge);
  const exists = getFilterOptions().some((option) => option.key === key);
  if (!exists) return;
  activeSiteFilter = key;
  renderCategorySites();
  siteFilters?.scrollIntoView({ behavior: "smooth", block: "center" });
}

window.WebShelfCategoryFilters = { applyBadge };

if (!pageTitle || !pageCount || !pageList || !pageIcon || !lucideIcon) {
  console.error("WebShelf: Category page HTML is incomplete.");
} else if (!currentCategory) {
  document.title = "Category Not Found - WebShelf";
  pageTitle.textContent = "Category not found";
  pageCount.textContent = "0 sites";
  pageIcon.style.color = "var(--text-muted)";
  lucideIcon.setAttribute("data-lucide", "circle-alert");
  siteFilters?.setAttribute("hidden", "");
  pageList.innerHTML = `
    <div class="category-empty">
      <h2>Category not found</h2>
      <p>The category you're looking for doesn't exist or the link may be incorrect.</p>
      <a href="./index.html" class="category-empty-link">Back to Directory</a>
    </div>
  `;
} else {
  document.title = `${currentCategory.title} - WebShelf`;
  if (categoryCanonical) categoryCanonical.href = `https://www.webshelf.link/category.html?type=${encodeURIComponent(currentCategory.key)}`;
  if (categoryDescription) categoryDescription.content = `Browse curated ${currentCategory.title} websites on WebShelf.`;
  pageTitle.textContent = currentCategory.title;
  pageIcon.style.color = currentCategory.accent || "var(--brand-purple)";
  lucideIcon.setAttribute("data-lucide", currentCategory.icon || "folder");
  renderCategorySites();
}

siteFilters?.addEventListener("click", (event) => {
  const button = event.target.closest("[data-site-filter]");
  if (!button) return;
  activeSiteFilter = button.dataset.siteFilter || "all";
  renderCategorySites();
});

document.addEventListener("webshelf-hidden-changed", renderCategorySites);
window.lucide?.createIcons?.();

;

// preview.js
// ==================================================
// INLINE SITE PREVIEW
// ==================================================

(() => {
  const safeText = (value) => typeof escapeWebShelfText === "function"
    ? escapeWebShelfText(value)
    : String(value ?? "");

  function normalizeUrl(url) {
    try {
      const value = new URL(url, window.location.href).href;
      return value.endsWith("/") ? value.slice(0, -1) : value;
    } catch {
      return String(url || "");
    }
  }

  function findSite(url) {
    const wanted = normalizeUrl(url);
    return WebShelfSites.find((site) => normalizeUrl(site.url) === wanted);
  }

  function safeArray(value) {
    return Array.isArray(value) ? value : [];
  }

  function mainLinkHTML(site) {
    return `
      <a class="site-preview-link site-preview-main-link" href="${safeText(site.url)}" target="_blank" rel="noopener noreferrer" data-preview-open-url="${safeText(site.url)}">
        Main site <span aria-hidden="true">↗</span>
      </a>`;
  }

  function mirrorLinksHTML(site) {
    const mirrors = safeArray(site.links).filter((link) => WebShelfRuntime.safeUrl(link?.url) && normalizeUrl(link.url) !== normalizeUrl(site.url));
    if (!mirrors.length) return "";

    return `
      <div class="site-preview-mirrors">
        <span class="site-preview-subheading">Mirrors & alternate links</span>
        <div class="site-preview-links">
          ${mirrors.map((link, index) => `
            <a class="site-preview-link" href="${safeText(link.url)}" target="_blank" rel="noopener noreferrer" data-preview-open-url="${safeText(site.url)}">
              ${safeText(link.label || `Mirror ${index + 1}`)} <span aria-hidden="true">↗</span>
            </a>`).join("")}
        </div>
      </div>`;
  }

  function descriptionHTML(site) {
    const description = String(site.description || "").trim();
    if (!description) return "";
    return `<p class="site-preview-description">${safeText(description)}</p>`;
  }

  function screenshotsHTML(site) {
    const screenshots = safeArray(site.screenshots).filter(src => WebShelfRuntime.safeUrl(src, true));
    if (!screenshots.length) return "";
    return `
      <section class="site-preview-section">
        <h4>Screenshots</h4>
        <div class="site-preview-screenshots">
          ${screenshots.map((src, index) => `
            <a href="${safeText(src)}" target="_blank" rel="noopener noreferrer" aria-label="Open ${safeText(site.name)} screenshot ${index + 1}">
              <img src="${safeText(src)}" alt="${safeText(site.name)} screenshot ${index + 1}" loading="lazy" decoding="async">
            </a>`).join("")}
        </div>
      </section>`;
  }

  function highlightsHTML(site) {
    const highlights = safeArray(site.highlights).filter((item) => item?.text);
    if (!highlights.length) return "";
    return `
      <section class="site-preview-section site-preview-highlights">
        <h4>Highlights</h4>
        <div class="site-preview-highlights-list">
          ${highlights.map((item) => {
            const type = item.type === "bad" ? "bad" : "good";
            return `<div class="site-preview-highlight ${type}"><span class="site-preview-highlight-symbol">${type === "bad" ? "−" : "+"}</span><span>${safeText(item.text)}</span></div>`;
          }).join("")}
        </div>
      </section>`;
  }

  function secondaryActionsHTML(site) {
    const supportUrl = `./support.html?type=broken-link&site=${encodeURIComponent(site.name)}&url=${encodeURIComponent(site.url)}`;
    const hiddenAction = typeof isSiteHidden === "function"
      ? `<button class="site-preview-action site-preview-hide" type="button" data-preview-hide="${safeText(site.url)}">${isSiteHidden(site.url) ? "Show in directory" : "Hide / Not interested"}</button>`
      : "";

    return `
      <div class="site-preview-personal-actions">
        <a class="site-preview-action site-preview-report" href="${safeText(supportUrl)}">Report this link</a>
        ${hiddenAction}
      </div>`;
  }

  let previewId = 0;
  function buildPreview(site) {
    const panel = document.createElement("div");
    panel.className = "site-inline-preview";
    panel.id = "webshelf-preview-" + (++previewId);
    panel.hidden = true;
    panel.dataset.previewUrl = site.url;

    panel.innerHTML = `
      <div class="site-inline-preview-inner">
        <div class="site-preview-heading">
          <div>
            <span class="site-preview-category">${safeText(site.category)}</span>
            <div class="site-preview-title-line"><h3>${safeText(site.name)}</h3></div>
            ${descriptionHTML(site)}
          </div>
        </div>

        <section class="site-preview-section">
          <h4>Links</h4>
          <div class="site-preview-links">${mainLinkHTML(site)}</div>
          ${mirrorLinksHTML(site)}
        </section>

        ${screenshotsHTML(site)}
        ${highlightsHTML(site)}
        ${secondaryActionsHTML(site)}
      </div>`;
    return panel;
  }

  function closeRow(row) {
    const button = row.querySelector(".site-preview-toggle");
    const panel = row.nextElementSibling;
    if (!button || !panel?.classList.contains("site-inline-preview")) return;
    if (panel.contains(document.activeElement)) button.focus();
    panel.hidden = true;
    button.classList.remove("active");
    button.setAttribute("aria-expanded", "false");
  }

  function closeAll(exceptRow = null) {
    document.querySelectorAll(".site-row, .activity-row").forEach((row) => {
      if (row !== exceptRow) closeRow(row);
    });
  }

  function toggleRow(row) {
    const button = row.querySelector(".site-preview-toggle");
    const panel = row.nextElementSibling;
    if (!button || !panel?.classList.contains("site-inline-preview")) return;
    const willOpen = panel.hidden;
    closeAll(row);
    panel.hidden = !willOpen;
    button.classList.toggle("active", willOpen);
    button.setAttribute("aria-expanded", String(willOpen));
  }

  function prepareRow(row) {
    if (row.dataset.previewReady === "true") return;
    const link = row.querySelector(".site-link, .activity-link");
    if (!link?.href) return;
    const site = findSite(link.href);
    if (!site) return;

    row.dataset.previewReady = "true";
    const button = document.createElement("button");
    button.className = "site-preview-toggle";
    button.type = "button";
    button.dataset.previewUrl = site.url;
    button.setAttribute("aria-label", `Show ${site.name} preview`);
    button.setAttribute("aria-expanded", "false");
    button.innerHTML = `<span aria-hidden="true">›</span>`;

    const remove = row.querySelector(".activity-remove, .activity-unhide");
    if (remove) row.insertBefore(button, remove);
    else row.appendChild(button);
    const panel = buildPreview(site);
    button.setAttribute("aria-controls", panel.id);
    row.insertAdjacentElement("afterend", panel);
  }

  function scan(root = document) {
    root.querySelectorAll(".site-row, .activity-row").forEach(prepareRow);
  }

  function showUndoToast(site) {
    document.querySelector(".webshelf-undo-toast")?.remove();
    const toast = document.createElement("div");
    toast.setAttribute("role", "status");
    toast.className = "webshelf-undo-toast";
    toast.innerHTML = `<span>${safeText(site.name)} hidden.</span><button type="button">Undo</button>`;
    document.body.appendChild(toast);

    const timer = window.setTimeout(() => toast.remove(), 5000);
    toast.querySelector("button")?.addEventListener("click", () => {
      window.clearTimeout(timer);
      if (typeof setSiteHidden === "function") setSiteHidden(site.url, false);
      toast.remove();
    });
  }

  document.addEventListener("click", (event) => {
    const toggle = event.target.closest(".site-preview-toggle");
    if (toggle) {
      event.preventDefault();
      event.stopPropagation();
      const row = toggle.closest(".site-row, .activity-row");
      if (row) toggleRow(row);
      return;
    }

    const previewLink = event.target.closest(".site-preview-link");
    if (previewLink) {
      const site = findSite(previewLink.dataset.previewOpenUrl);
      if (site && typeof addRecentlyViewed === "function") addRecentlyViewed(site);
      return;
    }

    const hide = event.target.closest("[data-preview-hide]");
    if (hide) {
      event.preventDefault();
      const site = findSite(hide.dataset.previewHide);
      if (!site || typeof setSiteHidden !== "function") return;
      const willHide = !isSiteHidden(site.url);
      setSiteHidden(site.url, willHide);
      closeAll();
      if (willHide) showUndoToast(site);
    }
  });

  document.addEventListener("webshelf-sites-rendered", () => scan());
  const observer = new MutationObserver(records => {
    for (const record of records) for (const node of record.addedNodes) {
      if (!(node instanceof Element)) continue;
      if (node.matches(".site-row, .activity-row")) prepareRow(node);
      if (node.querySelector(".site-row, .activity-row")) scan(node);
    }
  });
  observer.observe(document.body, { childList: true, subtree: true });
  scan();

  window.WebShelfPreview = {
    close: () => closeAll(),
    isOpen: () => Boolean(document.querySelector(".site-preview-toggle.active")),
    scan
  };
})();

;

// badge-filters.js
// ==================================================
// QUICK BADGE FILTERS
// ==================================================

(() => {
  function openBadgeFilter(badge) {
    if (!badge) return;

    if (window.WebShelfCategoryFilters?.applyBadge) {
      window.WebShelfCategoryFilters.applyBadge(badge);
      return;
    }

    if (window.WebShelfCollectionFilters?.applyBadge) {
      window.WebShelfCollectionFilters.applyBadge(badge);
      return;
    }

    window.location.href = `./collection.html?badge=${encodeURIComponent(badge)}`;
  }

  function isUsableBadge(element) {
    return element && !element.closest(".search-overlay") && element.hasAttribute("data-badge-filter");
  }

  document.addEventListener("click", (event) => {
    const badge = event.target.closest("[data-badge-filter]");
    if (!isUsableBadge(badge)) return;

    event.preventDefault();
    event.stopPropagation();
    openBadgeFilter(badge.dataset.badgeFilter);
  }, true);

  document.addEventListener("keydown", (event) => {
    if (event.key !== "Enter" && event.key !== " ") return;
    const badge = event.target.closest?.("[data-badge-filter]");
    if (!isUsableBadge(badge)) return;

    event.preventDefault();
    openBadgeFilter(badge.dataset.badgeFilter);
  });
})();

;

window.lucide?.createIcons?.();
